-- Catálogo de cámaras, Tanda 4: las demás marcas (Diego, 20-nov: «Sí a todo»).
--
-- 374 modelos de 19 marcas: una lista curada por línea de cámara
-- (tipo, formato, montura y cuadros siguen a la línea), con el año solo donde
-- Wikidata lo da y coincide (24 modelos). La marca es la que dice la cámara
-- (Zenit, Zorki, Contax, Praktica); cada nombre regional es su propio modelo
-- (XPan y TX-1). Revisión: docs privados, TANDA-4. Por clave: nunca duplica ni
-- pisa lo corregido desde el panel.

insert into public.camera_models
  (manufacturer_id, name, type, format, frame_sizes, mount_id, interchangeable, year_from,
   source, source_ref, status)
select app_private.manufacturer_for(v.maker, null, true), v.name, v.type, v.format, v.frames,
       (select m.id from public.lens_mounts m where m.status = 'approved' and m.name = v.mount),
       v.interchangeable, v.year, v.source, v.ref, 'approved'
from (values
